{
  "role": "Semantic assessor for a bounded Vietnamese teach-back lesson.",
  "goal": "Identify only the ideas and misconceptions actually evidenced by the learner, then propose one next Socratic move.",
  "success_criteria": [
    "Semantic paraphrases count; keyword overlap alone does not.",
    "Every supported or contradicted point includes a direct quote from student_explanation.",
    "Every misconception includes a direct quote and refers to an explicit false claim.",
    "Omitted knowledge is marked absent, never converted into a misconception."
  ],
  "classification_rules": [
    "Use misconception_assessments=[] when the learner is merely incomplete or vague.",
    "Do not infer beliefs from silence and never list every misconception as a default.",
    "out_of_scope=true only for an unrelated answer; insufficient_input=true for 'không biết', a tautology, or an answer too short to assess.",
    "copied_source=true only when wording substantially reproduces a supplied source phrase, not merely because the idea is correct.",
    "K3 includes biased or missing training data, new events after cutoff, and required evidence missing from context.",
    "K4 includes RAG, tools, sources, citations, or verification as mitigation; such mitigation does not guarantee 100% correctness.",
    "If awaiting_transfer=true, transfer_passed=true only for a new relevant example that demonstrates why a plausible answer still needs verification.",
    "Draft no more than one short Vietnamese Socratic question and do not reveal the complete answer."
  ],
  "rubric": {
    "task": "Hãy dạy lại cho agent vì sao một LLM có thể tạo ra câu trả lời nghe hợp lý nhưng sai, nêu một ví dụ và cách giảm rủi ro.",
    "knowledge_points": [
      {
        "id": "K1",
        "label": "Cơ chế sinh xác suất",
        "required": true,
        "ground_truth": "LLM tạo câu trả lời bằng cách dự đoán token tiếp theo theo một phân bố xác suất và lặp lại sau mỗi token; nó không mặc định thực hiện một phép tra cứu sự thật.",
        "accepted_signals": [
          "đoán hoặc dự đoán token tiếp theo",
          "chọn token theo xác suất",
          "nối token rồi dự đoán tiếp",
          "sinh văn bản theo pattern đã học"
        ]
      },
      {
        "id": "K2",
        "label": "Hợp lý không đồng nghĩa đúng",
        "required": true,
        "ground_truth": "Mục tiêu sinh một chuỗi có vẻ phù hợp với ngữ cảnh không tự động kiểm chứng rằng nội dung là sự thật, nên model có thể trả lời trôi chảy và tự tin nhưng sai.",
        "accepted_signals": [
          "nghe hợp lý nhưng sai",
          "không tự kiểm chứng sự thật",
          "tự tin không có nghĩa là đúng",
          "model tối ưu cho phần tiếp nối phù hợp"
        ]
      },
      {
        "id": "K3",
        "label": "Nguồn gây thiếu hoặc sai căn cứ",
        "required": true,
        "ground_truth": "Rủi ro tăng khi dữ liệu huấn luyện có thiên lệch hoặc thiếu, câu hỏi nằm sau knowledge cutoff, hoặc bằng chứng cần thiết không nằm trong context mà model đang nhìn thấy.",
        "accepted_signals": [
          "dữ liệu huấn luyện thiếu hoặc thiên lệch",
          "knowledge cutoff",
          "context window hữu hạn",
          "không có nguồn liên quan trong context"
        ]
      },
      {
        "id": "K4",
        "label": "Giảm rủi ro, không bảo đảm tuyệt đối",
        "required": true,
        "ground_truth": "RAG, tools, context phù hợp, trích dẫn và kiểm chứng có thể giảm hallucination nhưng không tạo bảo đảm đúng tuyệt đối; temperature thấp chủ yếu làm đầu ra ổn định hơn.",
        "accepted_signals": [
          "dùng RAG hoặc tool để lấy nguồn",
          "yêu cầu trích dẫn và kiểm chứng",
          "không có căn cứ thì nói không biết",
          "temperature thấp không thêm tri thức",
          "RAG không loại bỏ hoàn toàn hallucination"
        ]
      }
    ],
    "misconceptions": [
      {
        "id": "M1",
        "claim": "LLM luôn tra cứu một cơ sở dữ liệu sự thật trước khi trả lời."
      },
      {
        "id": "M2",
        "claim": "LLM cố ý nói dối hoặc biết chắc đáp án sai nhưng vẫn trả lời."
      },
      {
        "id": "M3",
        "claim": "Đặt temperature bằng 0 sẽ làm câu trả lời luôn đúng."
      },
      {
        "id": "M4",
        "claim": "Có RAG thì hệ thống hết hallucination và đạt độ chính xác 100%."
      },
      {
        "id": "M5",
        "claim": "Hallucination chỉ xảy ra khi hỏi thông tin mới sau knowledge cutoff."
      },
      {
        "id": "M6",
        "claim": "Context càng dài thì model luôn càng chính xác."
      }
    ],
    "source_phrases_for_copy_detection": [
      {
        "source_id": "D1-S10",
        "paraphrase": "LLM học cách đoán mảnh chữ tiếp theo trong ngữ cảnh; chatbot chỉ là một lớp sản phẩm bao quanh model nền."
      },
      {
        "source_id": "D1-S11",
        "paraphrase": "Đầu ra của Transformer là một phân bố xác suất trên các token ứng viên."
      },
      {
        "source_id": "D1-S12",
        "paraphrase": "Mỗi token được nối vào ngữ cảnh rồi model tiếp tục dự đoán token kế tiếp trong một vòng lặp tự hồi quy."
      },
      {
        "source_id": "D1-S16",
        "paraphrase": "Context và attention có giới hạn; với tài liệu dài nên lấy đúng đoạn liên quan vào context thay vì bắt model nhớ toàn bộ."
      },
      {
        "source_id": "D1-S20",
        "paraphrase": "Model có knowledge cutoff, tối ưu cho câu nghe hợp lý chứ không tự tra sự thật, và có context hữu hạn; RAG, tools và kiểm chứng giúp giảm rủi ro."
      },
      {
        "source_id": "D1-S29",
        "paraphrase": "Temperature và top_p chỉ thay đổi cách chọn token; chúng không làm model thông minh hơn hoặc thêm tri thức mới."
      },
      {
        "source_id": "T04-047",
        "paraphrase": "LLM dự đoán token tiếp theo, nối token vừa sinh vào chuỗi rồi lặp lại quá trình."
      },
      {
        "source_id": "T06-136",
        "paraphrase": "LLM không hiểu ngôn ngữ giống con người mà dự báo token theo xác suất; temperature tác động cách chọn token."
      },
      {
        "source_id": "T06-138",
        "paraphrase": "LLM không thể được giả định là đúng tuyệt đối; dữ liệu Internet dùng để huấn luyện có thể chứa thiên lệch."
      },
      {
        "source_id": "T06-139",
        "paraphrase": "Thiên lệch có thể đi qua các giai đoạn huấn luyện; RAG bổ sung dữ liệu và nguồn trích dẫn để giảm rủi ro."
      },
      {
        "source_id": "T06-148",
        "paraphrase": "Knowledge cutoff khiến model không có thông tin xảy ra sau mốc dữ liệu; tool tìm kiếm có thể bổ sung dữ liệu mới."
      },
      {
        "source_id": "T06-149",
        "paraphrase": "Context window giới hạn lượng thông tin model có thể nhìn trong một lần xử lý."
      }
    ]
  },
  "session_state": {
    "session_id": "20f78f0a-92cd-48ba-84ed-81b98bd09de8",
    "turn": 1,
    "covered_points": [],
    "unresolved_misconceptions": [],
    "attempts_by_gap": {},
    "awaiting_transfer": false,
    "transfer_passed": false,
    "mastery_complete": false
  },
  "student_explanation": "LLM sinh câu bằng cách dự đoán token tiếp theo theo xác suất. Vì mục tiêu là tạo phần tiếp nối hợp ngữ cảnh chứ không tự kiểm chứng sự thật, nó có thể nói rất trôi chảy nhưng sai. Rủi ro tăng nếu dữ liệu học bị lệch hoặc thiếu; nên dùng nguồn, RAG và kiểm chứng lại."
}

